            if len(na)>k: continue
            nd=ds[:]+[len(same)]
            for j in same: nd[j]+=1
            ans=rec(w+[c],max(m,c),nd,na)
            if ans is not None:return ans
        return None
    return rec([0],0,[0],set())

def cycle_power(r):
